#include <vector>
#include <cstddef>
#include <omp.h>

bool contains(std::vector<int> const& x, int target) {
    int found = 0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for default(none) shared(x, target, n) reduction(| : found)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        if (x[static_cast<std::size_t>(i)] == target) {
            found = 1;
        }
    }

    return found != 0;
}
